CREATE OR REPLACE FUNCTION public.igr_v4_prosecutor_respond(p_code text, p_player_token uuid, p_request_id bigint, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.igr_v4_players%rowtype; a public.igr_v4_actions%rowtype; proc public.igr_v4_players%rowtype; r public.igr_v4_rooms%rowtype;
begin
 select * into p from public.igr_v4_players where room_code=upper(trim(p_code)) and player_token=p_player_token; if not found then raise exception 'unauthorized'; end if;
 select * into a from public.igr_v4_actions where id=p_request_id and room_code=p.room_code and action_type='prosecutor_request' for update; if not found or a.payload->>'target'<>p.id::text or coalesce(a.payload->>'status','pending')<>'pending' then raise exception 'invalid request'; end if;
 select * into r from public.igr_v4_rooms where code=p.room_code for update; if r.status<>'playing' or r.phase<>'annex_procureur' or a.cycle<>r.cycle then raise exception 'request expired'; end if; select * into proc from public.igr_v4_players where id=a.player_id;
 update public.igr_v4_actions set payload=jsonb_set(payload,'{status}',to_jsonb(case when p_accept then 'accepted' else 'refused' end),true) where id=a.id;
 if p_accept then insert into public.igr_v4_actions(room_code,player_id,cycle,action_type,payload) values(r.code,proc.id,r.cycle,'prosecutor_success',jsonb_build_object('target',p.id,'target_pseudo',p.pseudo)); end if;
 insert into public.igr_v4_events(room_code,event_type,visibility,target_player_id,payload) values(r.code,'prosecutor_response','private',proc.id,jsonb_build_object('title',case when p_accept then 'ENTRETIEN ACCEPTÉ' else 'ENTRETIEN REFUSÉ' end,'text',p.pseudo||case when p_accept then ' accepte l’entretien.' else ' refuse l’entretien. La tentative ne consomme pas le quota réussi.' end));
 return jsonb_build_object('ok',true);
end $function$;


CREATE OR REPLACE FUNCTION public.igr_v4_start_game(p_code text, p_host_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare r public.igr_v4_rooms%rowtype;c int;p public.igr_v4_players%rowtype;spy_id uuid;idx int;roles text[]:=array[]::text[];rr text;chosen_count int;required_count int; begin select * into r from public.igr_v4_rooms where code=upper(trim(p_code)) and host_token=p_host_token for update;if not found then raise exception 'unauthorized';end if;if r.status<>'lobby' then raise exception 'already started';end if;select count(*) into c from public.igr_v4_players where room_code=r.code;if c>public.igr_v4_max_players(r.scenario_id) then raise exception 'too many players';end if;if exists(select 1 from public.igr_v4_players where room_code=r.code and not coalesce(audio_ready,false)) then raise exception 'all players must prepare audio';end if;if c<public.igr_v4_min_players(r.scenario_id) then raise exception 'not enough players';end if;if exists(select 1 from public.igr_v4_players where room_code=r.code and preferred_role is null) then raise exception 'all players must choose a role';end if;for idx in 0..c-1 loop roles:=array_append(roles,public.igr_v4_role_for_seat(r.scenario_id,idx,c));end loop;foreach rr in array roles loop select count(*) into chosen_count from public.igr_v4_players where room_code=r.code and preferred_role=rr;select count(*) into required_count from unnest(roles) z where z=rr;if chosen_count<>required_count then raise exception 'chosen roles do not match scenario composition';end if;end loop;update public.igr_v4_players set public_role=preferred_role,secret_role=preferred_role,ready=false where room_code=r.code;with ranked as(select id,row_number() over(order by random())::int slot from public.igr_v4_players where room_code=r.code and public_role='suspect') update public.igr_v4_players x set internal_slot=ranked.slot from ranked where x.id=ranked.id;if r.scenario_id in ('013','014','016','019','020') then select id into spy_id from public.igr_v4_players where room_code=r.code and public_role='suspect' order by random() limit 1;if spy_id is not null then update public.igr_v4_players set secret_role='espion' where id=spy_id;end if;end if;for p in select * from public.igr_v4_players where room_code=r.code loop update public.igr_v4_players set private_state=public.igr_v4_build_private_card(r.code,p.id) where id=p.id;end loop;update public.igr_v4_rooms set status='playing',cycle=0,phase='briefing',phase_started_at=now(),phase_ends_at=now()+interval '28 seconds',state=jsonb_build_object('heard','[]'::jsonb,'used_trames','{}'::jsonb,'used_news','{}'::jsonb,'annex_queue','[]'::jsonb,'annex_index',0,'video_active',false,'video_cut_until',null),updated_at=now() where code=r.code;insert into public.igr_v4_events(room_code,event_type,payload) select r.code,'context',jsonb_build_object('title','CONTEXTE','text',x.pack->>'context') from public.igr_v4_scenario_packs x where x.scenario_id=r.scenario_id;insert into public.igr_v4_events(room_code,event_type,payload) values(r.code,'phase',jsonb_build_object('title','BRIEFING DU DOSSIER','text','La musique du lobby s’arrête. Le MJ présente le contexte public avant la lecture des cartes privées.'));return jsonb_build_object('ok',true);end $function$;


CREATE OR REPLACE FUNCTION public.igr_v4_sync(p_code text, p_player_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare p public.igr_v4_players%rowtype;r public.igr_v4_rooms%rowtype;players jsonb;ev jsonb;suspects jsonb;pack jsonb;my_actions jsonb;protected_meta jsonb;field_meta jsonb;expert_meta jsonb;begin select * into p from public.igr_v4_players where room_code=upper(trim(p_code)) and player_token=p_player_token;if not found then raise exception 'unauthorized';end if;perform public.igr_v4_tick(p.room_code);select * into p from public.igr_v4_players where id=p.id;select * into r from public.igr_v4_rooms where code=p.room_code;select x.pack into pack from public.igr_v4_scenario_packs x where x.scenario_id=r.scenario_id;select coalesce(jsonb_agg(jsonb_build_object('id',id,'pseudo',pseudo,'seat_index',seat_index,'is_host',is_host,'public_role',public_role,'preferred_role',preferred_role,'ready',ready,'audio_ready',audio_ready,'avatar_rev',avatar_rev,'has_avatar',avatar_data is not null,'equipped_title',equipped_title,'equipped_badge',equipped_badge) order by seat_index),'[]'::jsonb) into players from public.igr_v4_players where room_code=r.code;ev:=public.igr_v4_visible_events(r.code,p);select coalesce(jsonb_agg(jsonb_build_object('id',id,'pseudo',pseudo) order by seat_index),'[]'::jsonb) into suspects from public.igr_v4_players where room_code=r.code and public_role='suspect';select coalesce(jsonb_agg(jsonb_build_object('id',id,'cycle',cycle,'action_type',action_type,'payload',payload,'created_at',created_at) order by id),'[]'::jsonb) into my_actions from public.igr_v4_actions where room_code=r.code and player_id=p.id;if p.public_role='juge' then select coalesce(jsonb_agg(jsonb_build_object('id',v->>'id','title',v->>'title','cost',coalesce((v->>'cost')::int,1))),'[]'::jsonb) into protected_meta from jsonb_array_elements(coalesce(pack->'protected','[]'::jsonb)) v;else protected_meta:='[]'::jsonb;end if;if p.public_role='inspecteur' then select coalesce(jsonb_agg(jsonb_build_object('id',v->>'id','title',v->>'title')),'[]'::jsonb) into field_meta from jsonb_array_elements(coalesce(pack->'field_actions','[]'::jsonb)) v;else field_meta:='[]'::jsonb;end if;if p.public_role='expert' then select coalesce(jsonb_agg(jsonb_build_object('id',v->>'id','title',v->>'title')),'[]'::jsonb) into expert_meta from jsonb_array_elements(coalesce(pack->'expert_actions','[]'::jsonb)) v;else expert_meta:='[]'::jsonb;end if;return jsonb_build_object('server_now',clock_timestamp(),'pending_requests',(select coalesce(jsonb_agg(jsonb_build_object('request_id',a.id,'from_pseudo',sender.pseudo) order by a.id),'[]'::jsonb) from public.igr_v4_actions a join public.igr_v4_players sender on sender.id=a.player_id where a.room_code=r.code and a.cycle=r.cycle and r.phase='annex_procureur' and a.action_type='prosecutor_request' and a.payload->>'target'=p.id::text and coalesce(a.payload->>'status','pending')='pending'),'room',jsonb_build_object('code',r.code,'scenario_id',r.scenario_id,'status',r.status,'cycle',r.cycle,'phase',r.phase,'phase_started_at',r.phase_started_at,'phase_ends_at',r.phase_ends_at,'state',r.state,'min_players',public.igr_v4_min_players(r.scenario_id),'max_players',public.igr_v4_max_players(r.scenario_id)),'player',jsonb_build_object('id',p.id,'pseudo',p.pseudo,'is_host',p.is_host,'ready',p.ready,'audio_ready',p.audio_ready,'public_role',p.public_role,'preferred_role',p.preferred_role,'equipped_title',p.equipped_title,'equipped_badge',p.equipped_badge,'secret_role',case when r.status in ('playing','finished') and r.phase<>'briefing' then p.secret_role else null end,'private_state',case when r.status in ('playing','finished') and r.phase<>'briefing' then p.private_state else '{}'::jsonb end),'players',players,'suspects',suspects,'events',ev,'my_actions',my_actions,'scenario',jsonb_build_object('context',pack->>'context','news',case when p.public_role='journaliste' then pack->'news' else '[]'::jsonb end,'protected',protected_meta,'field_actions',field_meta,'expert_actions',expert_meta,'truth',case when r.status='finished' then pack->'truth' else null end));end $function$;

